SELECT name,
  ROUND(AVG(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING), 2) AS centered_avg
FROM employees;

SELECT name,
  FIRST_VALUE(name) OVER (
    PARTITION BY dept_id ORDER BY salary DESC, id
    ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
  ) AS dept_top_earner
FROM employees;

SELECT name, hire_date,
  COUNT(*) OVER (ORDER BY hire_date RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS hires_so_far
FROM employees;

SELECT name,
  ROUND(PERCENT_RANK() OVER (PARTITION BY dept_id ORDER BY salary), 4) AS pct_rank
FROM employees;

SELECT name,
  ROUND(AVG(salary) OVER (ORDER BY hire_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), 2) AS trailing_avg
FROM employees;

SELECT name,
  LAG(salary, 2, 0) OVER (PARTITION BY dept_id ORDER BY hire_date, id) AS salary_two_hires_ago
FROM employees;

SELECT name, price,
  ROUND(SUM(price) OVER (ORDER BY price RANGE BETWEEN 10 PRECEDING AND 10 FOLLOWING), 2) AS nearby_sum
FROM products;
